'use strict';

const fs = require('fs');
const path = require('path');

const DEFAULTS = {
  port: 3000,
  host: '127.0.0.1',
};

const inputPath = path.join(__dirname, 'config.json');
const outputPath = path.join(__dirname, 'config.out.json');

function loadConfig(filePath) {
  const raw = fs.readFileSync(filePath, 'utf8').trim();
  if (raw === '') {
    return {};
  }
  return JSON.parse(raw);
}

function applyDefaults(config) {
  const merged = { ...config };
  for (const [key, value] of Object.entries(DEFAULTS)) {
    if (merged[key] === undefined || merged[key] === null) {
      merged[key] = value;
    }
  }
  return merged;
}

const config = applyDefaults(loadConfig(inputPath));

fs.writeFileSync(outputPath, `${JSON.stringify(config, null, 2)}\n`, 'utf8');

console.log(`wrote ${path.basename(outputPath)}: ${JSON.stringify(config)}`);

